Data structure from the backend:

There will be two endpoints:

1.GetProductionStepForEdit - that will provide you will all the needed information to generate the popup

Input query: ProductId(required), StepId, StartStateId,EndStateId - you will have to provide or StepId for edit, or StartStateId,EndStateId to create new one.

Output:

{noformat}{
// Measurements are needed for the steps in the wizard
    "measurements": [
      {
        "measurementId": 1,
        "height": 12,
        "width": 12,
        "depth": 12,
        "position": 2,
        "isDefault": true
      },
      {
        "measurementId": 2,
        "height": 12,
        "width": 123,
        "depth": 123,
        "position": 3,
        "isDefault": false
      },
      {
        "measurementId": 3,
        "height": 11,
        "width": 12,
        "depth": 32,
        "position": 1,
        "isDefault": false
      }
    ],
    //Those are the variants in the list, those are optional and should have the checkbox
    "workPieceVariants": [
      {
        "workPieceVariantId": 1,
        "workPieceId": 1,
        "description": "Glass frame 2"
      }
    ],
    //Workpice is the standard variant and is required 
    "workPiece": {
      "materialGroup": {
        "materialGroupId": 1,
        "name": "Glass"
      },
      "surfaceFinish": {
        "surfaceFinishId": 4,
        "name": "Sandblasted"
      },
      "workPieceId": 1,
      "name": "Glass",
      "finishedState": "Glass panel",
      "surfaceFinishId": 4,
      "materialGroupId": 1
    },
    //Production step - for new step this will only provid startstate and end state, other will be empty. 
    //On edit you will havel all the information 
    "productionStep": {
      "startState": {
        "stateId": 3,
        "description": "Glass",
        "nextStateId": 2,
        "stateType": 1,
        "productId": 11
      },
      "endState": {
        "stateId": 1,
        "description": "Product 11",
        "nextStateId": 0,
        "stateType": 4,
        "productId": 11
      },
      "stepMeasurementVariants": [],
      "producerId": 0,
      "productId": 0,
      "stepId": 0,
      "startStateId": 3,
      "endStateId": 1
    }
  }{noformat}

# CreateOrUpdateProductionStep - you will have to provide or StepId for edit, or StartStateId,EndStateId to create new one.

Input:

{noformat}{
//This is a list of max/min/standart measurement 
  "stepMeasurementVariants": [
    {
      "stepMeasurementVariantsId": 0,
      "measurementsId": 0,
      "orderProcessingTime": 0,
      "workHours": 0,
      "transportAndAssemblyCost": 0,
      "additionalCosts": 0,
      //This is the list of variants. You will have to provide workpiecId for every one. Standard will have
      // workPieceVariantId = 0. For all the other you have to provide the workPieceVariantId.
      "workPieceVariantsCost": [
        {
          "workPieceVariantCostId": 0,
          "workPieceId": 0,
          "workPieceVariantId": 0,
          "isStandard": true,
          "materialCost": 0,
          "canProduce": true
        }
      ]
    }
  ],
  "productId": 0,
  "stepId": 0,
  "startStateId": 0,
  "endStateId": 0
}{noformat}

